 void ProbeRangeMenu(){var entries=new List<(string,Action)>();for(float r=world.ProbeMinRange;r<=world.ProbeMaxRange;r*=2){float range=r;entries.Add((range.ToString("0.##")+" AU",()=>world.SetProbeRange(range)));}ShowPopup("Probe scan range",entries);}
 void ProbeFilterMenu(){var items=new List<(string,Action)>();foreach(string f in new[]{"All","Signatures","Anomalies","Ships","Custom"}){string filter=f;items.Add((filter,()=>{probeFilter=filter;probeResultsScroll=0;}));}foreach(string k in new[]{"Data","Relic","Gas","Wormhole","Combat","Ore","Ship","Drone","Structure"}){string kind=k;items.Add(((probeKinds.Contains(k)?"[x] ":"[ ] ")+k,()=>{if(!probeKinds.Add(kind))probeKinds.Remove(kind);probeFilter="Custom";}));}ShowPopup("Scan result filters",items);}
 void ProbePresetMenu(){var items=new List<(string,Action)>{("Save current formation",()=>world.SaveProbePreset("Custom "+(world.ProbePresets.Count+1)))};foreach(var p in world.ProbePresets){string name=p.Name;items.Add((name,()=>world.LoadProbePreset(name)));items.Add(("Delete "+name,()=>world.ProbePresets.RemoveAll(p=>p.Name==name)));}ShowPopup("Custom probe formations",items);}
 void ProbeScannerMenu(){var hit=ui.Hits.LastOrDefault(h=>h.Owner==ViewMode.Scanner.ToString()&&h.Rect.Contains(mouse.ToPoint()));var actions=new List<(string,Action)>();if(hit?.Tip.StartsWith("Probe result / ")==true){var s=world.UtilitySites.First(s=>s.Id==hit.Tip[15..]);world.ProbeSelection=s.Id;actions.Add(("Show Info",()=>ShowInformation("site/"+s.System+"/"+s.Id)));actions.Add(("Center probes on result",world.CenterUtilityProbes));actions.Add(("Focus map on result",()=>{FocusProbeEstimate(s);OpenProbeMap();}));if(world.ProbeWarpable(s)){actions.Add(("Warp to within 0 m",()=>world.BeginWarp(s.Id,0)));foreach(int d in new[]{10000,20000,30000,50000,70000,100000}){int range=d;actions.Add(("Warp to within "+SolarCatalog.Distance(range),()=>world.BeginWarp(s.Id,range)));}actions.Add(("Save location",()=>world.BookmarkProbeResult(s.Id)));}actions.Add(("Ignore result",()=>s.Ignored=true));actions.Add(("Ignore other results",()=>{foreach(var other in world.UtilitySites.Where(v=>v.System==world.SystemId&&v.Id!=s.Id))other.Ignored=true;}));}
 else if(hit?.Tip.StartsWith("Deployed probe / ")==true){var p=world.ScanProbes.First(p=>p.Id==hit.Tip[17..]);actions.Add(("Show Info",()=>ShowInformation("probe/"+p.Id)));actions.Add((p.Enabled?"Deactivate probe":"Activate probe",()=>p.Enabled=!p.Enabled));actions.Add(("Recover probe",()=>world.RecoverActiveProbes(p.Id)));actions.Add(("Destroy probe",()=>world.DestroyScanProbe(p.Id)));actions.Add(("Focus map on probe",()=>{probeMapFocus=DemoWorld.ProbePlannedAU(p);OpenProbeMap();}));actions.Add(("Set scan range",ProbeRangeMenu));}
 else{actions.Add(("Launch probes",()=>world.LaunchScanProbes()));actions.Add(("Recover active probes",()=>world.RecoverActiveProbes()));actions.Add(("Reconnect to lost probes",()=>world.ReconnectScanProbes()));actions.Add(("Analyze",()=>world.AnalyzeUtilityProbes()));actions.Add(("Cancel analysis",world.CancelProbeAnalysis));actions.Add(("Restore ignored results",()=>{foreach(var s in world.UtilitySites.Where(s=>s.System==world.SystemId))s.Ignored=false;}));actions.Add(("Open system map",OpenProbeMap));actions.Add(("Custom formations",ProbePresetMenu));}ShowPopup("Probe scanner",actions);}
